import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Атлас', quota: 42, status: 'active' },
  { id: 'p2', name: 'Меридиан', quota: 88, status: 'over' },
  { id: 'p3', name: 'Компас', quota: 15, status: 'paused' },
  { id: 'p4', name: 'Горизонт', quota: 67, status: 'active' },
  { id: 'p5', name: 'Орбита', quota: 100, status: 'over' },
  { id: 'p6', name: 'Вектор', quota: 30, status: 'paused' },
  { id: 'p7', name: 'Призма', quota: 54, status: 'active' },
  { id: 'p8', name: 'Дельта', quota: 9, status: 'paused' },
  { id: 'p9', name: 'Каскад', quota: 76, status: 'active' },
  { id: 'p10', name: 'Импульс', quota: 95, status: 'over' },
  { id: 'p11', name: 'Тандем', quota: 21, status: 'paused' },
];

const statusOptions: { value: ProjectStatus; label: string }[] = [
  { value: 'active', label: 'Активен' },
  { value: 'paused', label: 'На паузе' },
  { value: 'over', label: 'Превышена квота' },
];

const statusLabel: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Превышена квота',
};

const statusTone: Record<ProjectStatus, 'success' | 'default' | 'danger'> = {
  active: 'success',
  paused: 'default',
  over: 'danger',
};

const pageSize = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(
    statusOptions.map((option) => option.value),
  );
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((value) => value !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(statusOptions.map((option) => option.value));
    setPage(1);
  };

  const filtered = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const visible = filtered.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {statusOptions.map((option) => (
          <JxChip
            key={option.value}
            active={activeStatuses.includes(option.value)}
            removable={activeStatuses.includes(option.value)}
            onRemove={() => toggleStatus(option.value)}
            onClick={() => {
              if (!activeStatuses.includes(option.value)) toggleStatus(option.value);
            }}
          >
            {option.label}
          </JxChip>
        ))}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Нет проектов под фильтр"
          message="Попробуйте выбрать другие статусы или сбросьте фильтры."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: '16px',
                  padding: '12px 8px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <span
                  style={{
                    color: 'var(--jx-text)',
                    fontFamily: 'var(--jx-font-sans)',
                    fontWeight: 600,
                  }}
                >
                  {project.name}
                </span>
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                  <JxProgressCircle value={project.quota} showValue />
                  <JxBadge tone={statusTone[project.status]} dot>
                    {statusLabel[project.status]}
                  </JxBadge>
                </div>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

